import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  Grid,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from '@mui/material';
import axios from 'axios';
import ScrollableTableContainer from '../shared/ScrollableTableContainer';
import { buildApiUrl } from '../../config/apiConfig';

interface ExpertUser {
  _id: string;
  email: string;
  isActive: boolean;
  lastLogin?: string;
  profile?: {
    firstName?: string;
    lastName?: string;
    phone?: string;
  };
}

const emptyForm = {
  firstName: '',
  lastName: '',
  phone: '',
  email: '',
  password: '',
};

const AdminExpertUsers: React.FC = () => {
  const [users, setUsers] = useState<ExpertUser[]>([]);
  const [loading, setLoading] = useState(false);
  const [creating, setCreating] = useState(false);
  const [updatingId, setUpdatingId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [form, setForm] = useState(emptyForm);

  const load = useCallback(async () => {
    try {
      setLoading(true);
      const response = await axios.get(buildApiUrl('/admin/expert-users'), {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
      });
      setUsers(response.data?.data?.users || []);
    } catch (loadError: any) {
      if (loadError.response?.status !== 403 && loadError.response?.status !== 401) {
        setError('Failed to load expert consultants');
      }
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const createUser = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setError(null);
    setSuccess(null);
    try {
      setCreating(true);
      await axios.post(
        buildApiUrl('/admin/expert-users'),
        {
          email: form.email.trim(),
          password: form.password,
          profile: {
            firstName: form.firstName.trim(),
            lastName: form.lastName.trim(),
            phone: form.phone.trim(),
          },
        },
        { headers: { Authorization: `Bearer ${localStorage.getItem('token')}` } }
      );
      setSuccess('Expert consultant created. They can sign in on the login page.');
      setForm(emptyForm);
      load();
    } catch (createError: any) {
      setError(createError?.response?.data?.message || 'Failed to create expert consultant');
    } finally {
      setCreating(false);
    }
  };

  const setAccess = async (userId: string, isActive: boolean) => {
    setError(null);
    setSuccess(null);
    try {
      setUpdatingId(userId);
      const response = await axios.patch(
        buildApiUrl(`/admin/expert-users/${userId}/access`),
        { isActive },
        { headers: { Authorization: `Bearer ${localStorage.getItem('token')}` } }
      );
      const updated = response?.data?.data?.user;
      if (updated?._id) {
        setUsers((current) => current.map((user) => (user._id === updated._id ? updated : user)));
      } else {
        load();
      }
    } catch (accessError: any) {
      setError(accessError?.response?.data?.message || 'Failed to update expert consultant access');
    } finally {
      setUpdatingId(null);
    }
  };

  return (
    <Paper sx={{ p: 3, mb: 3 }}>
      <Typography variant="h6" sx={{ fontWeight: 700, mb: 1 }}>
        Expert consultants
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
        These accounts sign in on the login page and classify vouchers that would have used rupees times an emission factor. A consultant profile is also created for expert.consultant@sustainow.in when the server starts.
      </Typography>
      {error ? <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>{error}</Alert> : null}
      {success ? <Alert severity="success" sx={{ mb: 2 }} onClose={() => setSuccess(null)}>{success}</Alert> : null}
      <Box component="form" onSubmit={createUser} sx={{ mb: 3 }}>
        <Grid container spacing={2}>
          <Grid item xs={12} md={3}>
            <TextField fullWidth size="small" label="First Name" required value={form.firstName} onChange={(event) => setForm((current) => ({ ...current, firstName: event.target.value }))} />
          </Grid>
          <Grid item xs={12} md={3}>
            <TextField fullWidth size="small" label="Last Name" value={form.lastName} onChange={(event) => setForm((current) => ({ ...current, lastName: event.target.value }))} />
          </Grid>
          <Grid item xs={12} md={3}>
            <TextField fullWidth size="small" label="Phone" value={form.phone} onChange={(event) => setForm((current) => ({ ...current, phone: event.target.value }))} />
          </Grid>
          <Grid item xs={12} md={3}>
            <TextField fullWidth size="small" type="email" label="Email" required value={form.email} onChange={(event) => setForm((current) => ({ ...current, email: event.target.value }))} />
          </Grid>
          <Grid item xs={12} md={3}>
            <TextField fullWidth size="small" type="password" label="Temporary Password" required value={form.password} onChange={(event) => setForm((current) => ({ ...current, password: event.target.value }))} inputProps={{ minLength: 6 }} />
          </Grid>
          <Grid item xs={12} md={3} sx={{ display: 'flex', alignItems: 'center' }}>
            <Button type="submit" variant="contained" fullWidth disabled={creating}>
              {creating ? 'Adding consultant...' : 'Add expert consultant'}
            </Button>
          </Grid>
        </Grid>
      </Box>
      <ScrollableTableContainer component={Paper} variant="outlined">
        <Table size="small">
          <TableHead>
            <TableRow>
              <TableCell><strong>Name</strong></TableCell>
              <TableCell><strong>Email</strong></TableCell>
              <TableCell><strong>Last Login</strong></TableCell>
              <TableCell><strong>Status</strong></TableCell>
              <TableCell><strong>Access</strong></TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {loading ? (
              <TableRow>
                <TableCell colSpan={5} align="center">Loading expert consultants...</TableCell>
              </TableRow>
            ) : users.length === 0 ? (
              <TableRow>
                <TableCell colSpan={5} align="center">No expert consultants yet</TableCell>
              </TableRow>
            ) : users.map((user) => (
              <TableRow key={user._id} hover>
                <TableCell>
                  {[user.profile?.firstName, user.profile?.lastName].filter(Boolean).join(' ') || 'N/A'}
                </TableCell>
                <TableCell>{user.email}</TableCell>
                <TableCell>{user.lastLogin ? new Date(user.lastLogin).toLocaleDateString() : 'Never'}</TableCell>
                <TableCell>
                  <Chip label={user.isActive ? 'Active' : 'Inactive'} color={user.isActive ? 'success' : 'default'} size="small" />
                </TableCell>
                <TableCell>
                  <Button
                    size="small"
                    variant={user.isActive ? 'outlined' : 'contained'}
                    color={user.isActive ? 'error' : 'success'}
                    disabled={updatingId === user._id}
                    onClick={() => setAccess(user._id, !user.isActive)}
                  >
                    {updatingId === user._id ? 'Updating...' : user.isActive ? 'Remove Access' : 'Allow User'}
                  </Button>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </ScrollableTableContainer>
    </Paper>
  );
};

export default AdminExpertUsers;
