import React from 'react';
import {
  AppBar,
  Box,
  Button,
  Chip,
  Container,
  Stack,
  Toolbar,
  Typography,
} from '@mui/material';
import { Logout as LogoutIcon } from '@mui/icons-material';
import BrandLogoMark from '../BrandLogoMark';
import {
  formatOrganizationType,
  getPortalRoleLabel,
} from '../../constants/adminPortal';
import { getAdminPortalUser } from '../../utils/adminPortalSession';
import { useRegistration } from '../../context/RegistrationContext';
import { isViewRoleProfile } from '../../utils/authRole';
import ReviewerReadOnlyBanner from './ReviewerReadOnlyBanner';

interface AdminPortalLayoutProps {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
  maxWidth?: 'lg' | 'xl' | false;
}

const AdminPortalLayout: React.FC<AdminPortalLayoutProps> = ({
  title,
  subtitle,
  children,
  maxWidth = 'xl',
}) => {
  const { logout } = useRegistration();
  const portalUser = getAdminPortalUser();
  const isReviewer = isViewRoleProfile();
  const displayName = [
    portalUser?.profile?.firstName,
    portalUser?.profile?.lastName,
  ]
    .filter(Boolean)
    .join(' ')
    .trim();
  const organizationLabel = formatOrganizationType(
    portalUser?.accessCredentials?.organizationType,
  );

  const handleLogout = () => {
    logout({ redirectTo: '/login' });
  };

  return (
    <Box sx={{ minHeight: '100vh', bgcolor: 'grey.100' }}>
      <AppBar position="static" color="default" elevation={1}>
        <Toolbar sx={{ gap: 2, flexWrap: 'wrap', py: 1 }}>
          <BrandLogoMark width={180} />
          <Box sx={{ flexGrow: 1, minWidth: 200 }}>
            <Typography variant="subtitle2" color="text.secondary">
              {isReviewer ? 'Reviewer portal' : 'Admin portal'}
            </Typography>
            <Typography variant="body2" sx={{ fontWeight: 600 }}>
              {displayName || portalUser?.email || 'Signed in'}
            </Typography>
          </Box>
          <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
            <Chip
              size="small"
              color={isReviewer ? 'info' : 'primary'}
              label={getPortalRoleLabel(portalUser?.role)}
            />
            {portalUser?.accessCredentials?.organizationName && (
              <Chip
                size="small"
                variant="outlined"
                label={portalUser.accessCredentials.organizationName}
              />
            )}
            <Chip size="small" variant="outlined" label={organizationLabel} />
          </Stack>
          <Button
            variant="outlined"
            size="small"
            startIcon={<LogoutIcon />}
            onClick={handleLogout}
          >
            Logout
          </Button>
        </Toolbar>
      </AppBar>

      <Container maxWidth={maxWidth} sx={{ py: 4 }}>
        <Box sx={{ mb: 3 }}>
          <Typography variant="h4" component="h1" sx={{ fontWeight: 700 }}>
            {title}
          </Typography>
          {subtitle && (
            <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}>
              {subtitle}
            </Typography>
          )}
        </Box>

        {isReviewer && <ReviewerReadOnlyBanner />}
        {children}
      </Container>
    </Box>
  );
};

export default AdminPortalLayout;
